219	      <h4>Supporting evidence</h4>{ev.length?<ul>{ev.map((e,i)=><li key={i}>{str(e.description)}{e.reference?` · ${str(e.reference)}`:''}</li>)}</ul>:<p>None recorded. Approval needs at least one item.</p>}
220	      {['nominated','under_review'].includes(status) && <Action action="add_recognition_evidence" title="Add evidence" initial={{recognitionId:x.id}} command={command}><Field name="description" title="What the evidence shows" area/><Field name="reference" title="Reference (optional)" required={false}/></Action>}
221	      {status==='nominated' && <Action action="start_recognition_review" title="Start review" initial={{recognitionId:x.id}} command={command}/>}
222	      {status==='under_review' && <Action action="decide_recognition" title="Record decision" initial={{recognitionId:x.id}} command={command}><Select name="decision" title="Decision" options={['approved','rejected']}/><Field name="recognitionDate" title="Recognition date (blank for today)" type="date" required={false}/><Field name="note" title="Decision and reason" area/></Action>}
223	      {status==='approved' && <><h4>Approved benefits and fulfilment</h4>{bs.length?<ul>{bs.map(b=><li key={str(b.id)}>{str(b.benefit)} · <strong>{b.outcome?`${label(b.outcome)}: ${str(b.fulfilment_note)}`:'Approved'}</strong>{!b.outcome && <Action action="record_benefit_fulfilment" title="Record outcome" initial={{benefitId:b.id}} command={command}><Select name="outcome" title="Outcome" options={['fulfilled','withdrawn']}/><Field name="note" title="Fulfilment note"/></Action>}</li>)}</ul>:<p>No benefits approved.</p>}
224	        <Action action="approve_recognition_benefit" title="Approve a benefit" initial={{recognitionId:x.id}} command={command}><Field name="benefit" title="Benefit (manual; no payment is made from here)"/></Action>
225	        <details><summary>Correct the recorded rationale or date</summary><Action action="correct_recognition" title="Record correction" initial={{recognitionId:x.id}} command={command}><Field name="recognitionDate" title="Corrected recognition date" type="date" required={false}/><Field name="rationale" title="Corrected rationale" area required={false}/><Field name="reason" title="Reason for the correction" area/></Action></details>
226	        <Action action="revoke_recognition" title="Revoke recognition" initial={{recognitionId:x.id}} command={command}><Field name="reason" title="Reason for revocation" area/></Action></>}
227	      {cs.length>0 && <><h4>Corrections</h4><ul>{cs.map((c,i)=><li key={i}>{new Date(str(c.created_at)).toLocaleDateString('en-GB')} · {str(c.reason)}</li>)}</ul></>}</details>}):<Empty text="No nominations yet."/>}</section>
228	}
229	
230	function ProfilePanel({p,command}:{p:Row;command:Command}) {
231	  const versions=rows(p.versions),open=versions.find(v=>['draft','changes_requested','submitted'].includes(str(v.status))),pub=(p.publication||null) as Row|null
232	  const latest=open||versions[0]
233	  return <section className="ex-panel"><p className="ex-overline">PERSONAL WEB PAGE</p><h2>Your ScaleSmiths partner page</h2>
234	    {!p.eligible?<p>A personal web page becomes available when you have five qualifying clients and the programme rules are approved. Nothing is published without your consent and a founder&apos;s approval.</p>:<>
235	    <p>Prepare the wording for your page. It is reviewed by a founder and, if approved, kept as a fixed version. Nothing is public until a founder publishes it{p.publicationEnabled?'':', and public publication is not switched on yet'}. Private contact details are never published: enquiries are directed through ScaleSmiths.</p>
