237	    {pub?.status==='live' && <Action action="withdraw_profile_consent" title="Withdraw my consent and remove my page" command={command}><p>Your page is removed at once. You do not need a founder&apos;s approval.</p></Action>}
238	    {open?.status==='submitted'?<><h3>With a founder for review</h3><dl><div><dt>Display name</dt><dd>{str(open.display_name)}</dd></div><div><dt>Biography</dt><dd className="ex-prewrap">{str(open.biography)}</dd></div><div><dt>Operating area</dt><dd>{str(open.operating_area)}</dd></div></dl><p>You cannot change it while it is being reviewed.</p></>:<>
239	      {Boolean(open?.feedback) && <p role="status"><strong>Founder feedback:</strong> {str(open?.feedback)}</p>}
240	      <Action action="save_profile_draft" title={open?'Save draft':'Start a draft'} command={command}><Field name="displayName" title="Display name (your own name or business name)" value={str(open?.display_name)}/><Field name="biography" title="Professional biography (20 to 1,200 characters; no contact details)" area value={str(open?.biography)}/><Field name="operatingArea" title="Geographic operating area" value={str(open?.operating_area)}/><Select name="enquiryMode" title="How enquiries are directed" options={['scalesmiths_contact','referral_code']}/></Action>
241	      {open && <><h3>Publication consent</h3><p className="ex-note">{str(p.consentText)}</p><p>{open.consent_at?`Consent recorded for the current wording on ${new Date(str(open.consent_at)).toLocaleDateString('en-GB')}. Changing the wording clears it.`:'No consent is recorded for the current wording.'}</p>
242	        <Action action="record_profile_consent" title="Record my consent" initial={{versionId:open.id}} command={command}><Check name="accept" title="I have read and agree to the statement above"/></Action>
243	        <Action action="submit_profile" title="Submit for founder review" initial={{versionId:open.id}} command={command}/></>}</>}
244	    {latest && !open && <p>Latest version: {label(latest.status)}.{latest.feedback?` Feedback: ${str(latest.feedback)}`:''}</p>}</>}</section>
