'use client'

import { FounderQualification } from '@/components/ascend/FounderQualification'
import { FoundingPartnerBadge } from './FoundingPartnerBadge'
import { useCallback, useEffect, useState, type FormEvent, type ReactNode } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { signOut } from 'next-auth/react'
import { ArrowUpRight, BookOpen, BriefcaseBusiness, PoundSterling, LayoutDashboard, Plus, ShieldCheck, Users } from 'lucide-react'
import { DISCOVERY_FIELDS, PARTNER_TRANSITIONS } from '@/lib/expansion'
import { formatPence, standardCommissionTerms } from '@/lib/expansion-finance'
import { csvCell } from '@/lib/command-centre'
import { ApplicantRetention } from './ApplicantRetention'
import { RecruitmentPanel } from './RecruitmentPanel'
import { PartnerNextSteps } from './PartnerNextSteps'
import { FounderOperations, MeetingPrepToggle, PartnerToday, ProspectGuidance } from './PartnerWorkspacePanels'
import { SafeMarkdown } from '@/components/empower/SafeMarkdown'
import './expansion.css'

type Row = Record<string, unknown>
type Snapshot = {workspace:Record<string,unknown>;finance:Record<string,unknown>;withdrawals?:Record<string,unknown>;programme?:Record<string,unknown>;programmeAdmin?:Record<string,unknown>;toolkit?:unknown;toolkitAdmin?:Record<string,unknown>;meetings?:unknown;researchAdmin?:Record<string,unknown>;recognitionAdmin?:Record<string,unknown>;recognition?:Record<string,unknown>;profile?:Record<string,unknown>;profilesAdmin?:Record<string,unknown>;contentAdmin?:Record<string,unknown>}
type Command = (input:Row)=>Promise<Row>
const str = (value:unknown) => value == null ? '' : String(value)
const rows = (value:unknown): Row[] => Array.isArray(value) ? value : []
const label = (value:unknown) => str(value).replaceAll('_',' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/^./,first=>first.toUpperCase()).replace(/\bseo\b/gi,'SEO')
const money = (value:unknown) => formatPence(str(value || '0'))
const EMAIL_OUTCOMES: Record<string,string> = {sent:'email sent',failed:'email could not be delivered; contact them directly',not_configured:'email is not configured; contact them directly',disabled:'partner email is switched off; contact them directly'}
/** Plain-language outcome of any partner email a founder decision queued. */
function emailOutcome(result:unknown) {
  const list = (result as {notifications?:{kind:string;status:string}[]}|undefined)?.notifications
  return list?.length ? ' '+list.map(n=>`${n.kind.replaceAll('_',' ')}: ${EMAIL_OUTCOMES[n.status]||n.status}.`).join(' ') : ''
}

export function ExpansionWorkspace({founder=false,academy=false,resources=false,knowledge=false,objections=false,unified=false,pipeline=false,handoffs=false,performance=false,commandCentre=false,revenue=false}:{founder?:boolean;academy?:boolean;resources?:boolean;knowledge?:boolean;objections?:boolean;unified?:boolean;pipeline?:boolean;handoffs?:boolean;performance?:boolean;commandCentre?:boolean;revenue?:boolean}) {

  const [data,setData] = useState<Snapshot|null>(null)
  const [error,setError] = useState('')
  const [tab,setTab] = useState('overview')
  const [search,setSearch] = useState('')
  const [resourceSearch,setResourceSearch] = useState('')
  const [resourceCategory,setResourceCategory] = useState('all')
  const [selected,setSelected] = useState('')
  const [invitation,setInvitation] = useState('')
  const endpoint = founder ? '/api/expansion' : '/api/partner'
  const refresh = useCallback(async (signal?:AbortSignal) => {
    const deadline = AbortSignal.timeout(30_000)
    const response = await fetch(endpoint, { cache: 'no-store', signal: signal ? AbortSignal.any([signal, deadline]) : deadline })
    const result = await response.json()
    if (!response.ok) throw new Error(result.error || 'Unable to load workspace.')
    setData(result); setError('')
  },[endpoint])
  useEffect(()=>{const controller = new AbortController(); refresh(controller.signal).catch(e=>{if(e.name!=='AbortError') setError(e.message)}); return ()=>controller.abort()},[refresh])
  const command:Command = async input => {
    let response: Response
    let result
    try {
      response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
        signal: AbortSignal.timeout(45_000),
      })
      result = await response.json()
    } catch {
      throw new Error('The response was interrupted. Refresh the records and verify the outcome before retrying.')
    }
    if (!response.ok) throw new Error(result.error || 'Change was rejected.')
    if (result.result?.invitationToken) setInvitation(`${window.location.origin}/partner/activate#token=${result.result.invitationToken}`)
    try {
      await refresh()
    } catch {
      setError('The change was recorded, but the displayed records could not be refreshed. Reload the workspace before another change.')
    }
    return result.result || {}
  }
  const workspace = data?.workspace || {}; const finance = data?.finance || {}; const withdrawals = data?.withdrawals || {}; const programme = data?.programme || {}; const programmeAdmin = data?.programmeAdmin || {}; const toolkitAdmin = data?.toolkitAdmin || {}; const researchAdmin = data?.researchAdmin || {}; const recognitionAdmin = data?.recognitionAdmin || {}; const recognition = data?.recognition || {}; const profile = data?.profile || {}; const profilesAdmin = data?.profilesAdmin || {}; const contentAdmin = data?.contentAdmin || {}
  const opportunities = rows(workspace.opportunities)
  const active = opportunities.find(row=>row.id===selected)
  const items = [{id:'overview',name:'Overview',icon:LayoutDashboard},{id:'pipeline',name:'Prospects & scope',icon:BriefcaseBusiness},{id:'resources',name:'Resource library',icon:BookOpen},{id:'finance',name:'Commission centre',icon:PoundSterling},...(founder?[{id:'research',name:'Research & allocation',icon:BriefcaseBusiness},{id:'recognition',name:'Recognition',icon:ShieldCheck},{id:'profiles',name:'Web pages',icon:BookOpen},{id:'programme',name:'Programme',icon:Users},{id:'operations',name:'Partner operations',icon:ShieldCheck}]:[{id:'achievements',name:'Achievements',icon:ShieldCheck},{id:'profile',name:'My web page',icon:BookOpen},{id:'referrals',name:'Referrals',icon:Users},{id:'onboarding',name:'Onboarding',icon:BookOpen},{id:'meetings',name:'Meetings',icon:LayoutDashboard}]),...(founder?[{id:'recruitment',name:'Recruitment',icon:Users},{id:'capacity',name:'Delivery capacity',icon:ShieldCheck}]:[]),...(founder && data?.contentAdmin?.enabled===true?[{id:'content',name:'Content',icon:BookOpen}]:[])]
  // Operation Ascend B2.3: ?tab=<id>&opportunity=<uuid> opens a tab (and an opportunity) directly, so command-centre items land on the record.
  useEffect(()=>{const p=new URLSearchParams(window.location.search);const t=p.get('tab'),o=p.get('opportunity');if(t&&items.some(i=>i.id===t))setTab(t);if(o&&/^[0-9a-f-]{36}$/i.test(o))setSelected(o)
    // eslint-disable-next-line react-hooks/exhaustive-deps -- read the URL once on arrival
  },[])
  return <div className={`expansion ${founder?'expansion-founder':''}`}>
    <header className="ex-header"><a href={founder?'/expansion':'/partner'} className="ex-brand"><Image src="/brand/favicon.png" alt="ScaleSmiths emblem" width={38} height={38} unoptimized /><span>SCALESMITHS<small>{founder?'COMMERCIAL OPERATIONS':'INDEPENDENT PARTNER NETWORK'}</small></span></a><div className="ex-header-right"><span className="ex-badge">{founder?'Founder workspace':'Partner workspace'}</span>{!founder && <button className="ex-link" onClick={()=>signOut({callbackUrl:'/login'})}>Sign out</button>}</div></header>
    <div className="ex-body"><aside className="ex-sidebar"><p className="ex-overline">YOUR WORKSPACE</p><nav aria-label="Partner workspace">{items.map(({id,name,icon:Icon})=><button key={id} aria-current={tab===id?'page':undefined} onClick={()=>{setTab(id);setSelected('')}}><Icon size={18}/>{name}</button>)}</nav>{!founder && performance && <Link className="ex-academy-link" href="/partner/performance"><ShieldCheck size={18}/>My performance<small>Your progress and achievements</small></Link>}{!founder && handoffs && <Link className="ex-academy-link" href="/partner/handoffs"><BriefcaseBusiness size={18}/>Delivery handoffs<small>Your accepted client projects</small></Link>}{!founder && academy && <Link className="ex-academy-link" href="/partner/academy"><BookOpen size={18}/>Partner Academy<small>Optional learning</small></Link>}{!founder && resources && <Link className="ex-academy-link" href="/partner/resources"><BookOpen size={18}/>Resource Centre<small>Approved material</small></Link>}{!founder && knowledge && <Link className="ex-academy-link" href="/partner/knowledge"><BookOpen size={18}/>Knowledge Base<small>Approved answers</small></Link>}{!founder && objections && <Link className="ex-academy-link" href="/partner/objections"><BookOpen size={18}/>Objection handling<small>Approved responses</small></Link>}{!founder && unified && <Link className="ex-academy-link" href="/partner/guidance"><BookOpen size={18}/>Find guidance<small>Search everything</small></Link>}<div className="ex-sidebar-note"><ShieldCheck size={20}/><strong>You sell. We deliver.</strong><p>Scope, pricing and delivery commitments require ScaleSmiths approval.</p></div></aside>

    <main className="ex-main" id="partner-main"><div className="ex-page-heading"><div><p className="ex-overline">OPERATION EXPANSION</p><h1>{items.find(item=>item.id===tab)?.name}</h1><p>{founder?'A clear view of people, pipeline and financial commitments.':`Welcome${workspace.displayName?`, ${workspace.displayName}`:''}. Build relationships. Create opportunities.`}</p></div><button className="ex-button" onClick={()=>{setTab('pipeline');setSelected('')}}><Plus size={17}/>{founder?'Review pipeline':'Register prospect'}</button></div>
    {error && <div className="ex-error" role="alert">{error}<button onClick={()=>refresh().catch(e=>setError(e.message))}>Retry</button></div>}
    {!data && !error && <div role="status" className="ex-empty">Loading your authorised workspace…</div>}
    {data && <>
      {tab==='overview' && <><div className="ex-metrics">{founder?<><Metric name="Active partners" value={str(rows(workspace.partners).filter(r=>r.active).length)} note="Activated identities"/><Metric name="Applications" value={str(rows(workspace.applications).length)} note="Latest 200 applications"/><Metric name="Registered opportunities" value={str(opportunities.length)} note="Latest 500 opportunities"/><Metric name="Commission liability" value={money(rows(finance.partners).reduce((s,r)=>s+BigInt(str(r.earned_pence))-BigInt(str(r.paid_pence)),BigInt(0)))} note="Earned less recorded paid"/></>:<><Metric name="Earned this month" value={money(finance.earnedThisMonthPence)} note="Verified qualifying collections"/><Metric name="Earned awaiting payment" value={money(finance.unpaidPence)} note="Earned less paid; may include adjustments"/><Metric name="Lifetime paid" value={money(finance.paidPence)} note="Manually reconciled settlements"/><Metric name="Conditional commission" value={money(finance.conditionalPence)} note="Accepted-contract potential; not earned"/></>}</div>{founder && commandCentre && <p><a className="ex-link" href="/expansion/command">Open the sales command centre</a></p>}{founder && revenue && <p><a className="ex-link" href="/expansion/revenue">Open revenue intelligence</a></p>}{founder && <FounderOperations ops={workspace.operations as never} onTab={setTab}/>}{!founder && <PartnerNextSteps academy={academy} resources={resources} knowledge={knowledge} opportunities={opportunities.length} onPipeline={()=>setTab('pipeline')}/>}{!founder && unified && <PartnerToday onOpenOpportunity={(id)=>{setSelected(id);setTab('pipeline')}} onTab={setTab}/>}<section className="ex-panel"><div className="ex-section-heading"><div><p className="ex-overline">YOUR NEXT OPPORTUNITY</p><h2>Relationships become growth.</h2></div><ArrowUpRight size={26}/></div><p>Register a business, understand its goals and submit a clear discovery. ScaleSmiths reviews the scope and delivery capacity before any commitment.</p><button className="ex-button" onClick={()=>setTab('pipeline')}>Open prospect workspace <ArrowUpRight size={16}/></button></section><div className="ex-columns"><section className="ex-panel"><h2>Recent opportunity activity</h2>{opportunities.length?opportunities.slice(0,5).map(row=><button className="ex-list-row" key={str(row.id)} onClick={()=>{setSelected(str(row.id));setTab('pipeline')}}><span>{str(row.business_name)}</span><span className="ex-badge">{label(row.status)}</span></button>):<Empty text="Your first relationship starts here. Register a business to begin discovery."/>}</section><Capacity data={rows(workspace.capacity)} founder={founder}/></div></>}
      {tab==='pipeline' && <><div className="ex-columns"><section className="ex-panel"><h2>Register a prospect</h2>{founder?<p>Prospects are registered by activated partners. Review submitted scope in the list below.</p>:<Action title="Register business" action="register" command={command}><Field name="businessName" title="Business name"/><Field name="website" title="Business website" placeholder="example.co.uk"/><Field name="companyNumber" title="Company number (optional)" required={false}/><Field name="contactName" title="Authorised contact (optional)" required={false}/><Field name="contactEmail" title="Business contact email (optional)" type="email" required={false}/><Field name="region" title="Region (optional)" required={false}/><Field name="country" title="Customer country, two-letter code such as GB (needed before a contract can be accepted)" required={false}/><Field name="industry" title="Industry (optional)" required={false}/></Action>}</section><section className="ex-panel"><h2>Prospect pipeline</h2>{!founder && pipeline && <p><a className="ex-link" href="/partner/pipeline">Open the full pipeline board</a></p>}<label className="ex-field">Search businesses<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Business name or stage"/></label>{opportunities.filter(row=>`${row.business_name} ${row.status}`.toLowerCase().includes(search.toLowerCase())).map(row=><button key={str(row.id)} className="ex-list-row" onClick={()=>setSelected(str(row.id))}><span><strong>{str(row.business_name)}</strong><small>{founder?str(row.partner_name):str(row.website_url)}</small></span><span className="ex-badge">{row.allocated?'Allocated · ':''}{label(row.status)}</span></button>)}{!opportunities.length && <Empty text="No registered prospects. Your pipeline will appear here."/>}</section></div>{active && <Opportunity key={str(active.id)} row={active} founder={founder} command={command} capacity={rows(workspace.capacity)} clients={rows(workspace.clients)} exclusivities={rows(workspace.exclusivities)} sectors={rows(workspace.sectors)} exclusivityStatus={str((workspace.exclusivityStatus as Row|undefined)?.[str(active.id)])}/>}{active && !founder && unified && <ProspectGuidance key={`guidance-${str(active.id)}`} opportunityId={str(active.id)} onRequestHelp={()=>setTab('meetings')}/>}</>}
      {tab==='resources' && <><section className="ex-panel"><p className="ex-overline">APPROVED KNOWLEDGE</p><h2>Present with confidence.</h2><p>Published resources are approved for the stated audience. Client-facing materials must not contain internal commission or founder information.</p><div className="ex-form-grid"><label className="ex-field">Search approved resources<input value={resourceSearch} onChange={e=>setResourceSearch(e.target.value)}/></label><label className="ex-field">Category<select value={resourceCategory} onChange={e=>setResourceCategory(e.target.value)}><option value="all">All categories</option>{Array.from(new Set(rows(workspace.resources).map(r=>str(r.category)))).map(c=><option key={c}>{c}</option>)}</select></label></div>{rows(workspace.resources).filter(row=>(founder || row.status==='published') && (resourceCategory==='all' || row.category===resourceCategory) && (str(row.title)+' '+str(row.content)).toLowerCase().includes(resourceSearch.toLowerCase())).map(row=><details key={str(row.id)} className="ex-resource"><summary>{str(row.title)} <span className="ex-badge">{str(row.audience)} · v{str(row.version)}{founder?` · ${str(row.status)}`:''}</span></summary><small>{str(row.category)}</small><p className="ex-prewrap">{str(row.content)}</p>{founder && row.status!=='archived' && <Action action="resource_status" title="Update publication" command={command} initial={{id:row.id}}><Select name="status" title="Publication state" options={row.status==='draft'?['published','archived']:['archived']}/></Action>}</details>)}{!rows(workspace.resources).length && <Empty text="Approved resources will appear here when published by ScaleSmiths."/>}</section>{founder && <section className="ex-panel"><h2>Publish an approved resource version</h2><Action action="resource" title="Save resource version" command={command}><Field name="title" title="Title"/><Field name="category" title="Category"/><Field name="version" title="Version" type="number" value="1"/><Select name="audience" title="Audience" options={['partner','client']}/><Select name="status" title="Publication" options={['draft','published']}/><Field name="content" title="Approved text content" area/></Action></section>}</>}
      {tab==='achievements' && !founder && <><RecognitionPanel o={recognition}/><AchievementCentre o={programme}/></>}
      {tab==='referrals' && !founder && <ReferralsPanel o={programme} command={command}/>}
      {tab==='onboarding' && !founder && <ToolkitView items={rows(data?.toolkit)} academy={academy}/>}
      {tab==='meetings' && !founder && <MeetingsView meetings={rows(data?.meetings)} opportunities={opportunities} command={command} academy={academy} unified={unified}/>}
      {tab==='operations' && founder && <OperationsAdmin toolkit={toolkitAdmin} meetings={rows(data?.meetings)} command={command}/>}
      {tab==='profiles' && founder && <ProfilesAdmin a={profilesAdmin} command={command}/>}
      {tab==='content' && founder && contentAdmin.enabled===true && <ContentStudio a={contentAdmin} command={command}/>}
      {tab==='profile' && !founder && <ProfilePanel p={profile} command={command}/>}
      {tab==='recognition' && founder && <RecognitionAdmin r={recognitionAdmin} command={command}/>}
      {tab==='research' && founder && <ResearchAdmin r={researchAdmin} sectors={rows(workspace.sectors)} exclusivities={rows(workspace.exclusivities)} command={command}/>}
      {tab==='programme' && founder && <ProgrammeAdmin a={programmeAdmin} command={command}/>}
      {tab==='finance' && <Finance founder={founder} finance={finance} workspace={workspace} command={command}/>}
      {tab==='finance' && !founder && <WithdrawalCentre w={withdrawals} command={command}/>}
      {tab==='finance' && founder && <WithdrawalAdmin w={withdrawals} command={command}/>}
      {tab==='finance' && founder && <MarketsAdmin markets={rows(workspace.markets)} command={command}/>}
      {tab==='finance' && founder && <SectorsAdmin sectors={rows(workspace.sectors)} command={command}/>}
      {tab==='finance' && founder && <AreasAdmin areas={rows(workspace.areas)} command={command}/>}
      {tab==='finance' && founder && <ExclusivityAdmin exclusivities={rows(workspace.exclusivities)} sectors={rows(workspace.sectors)} clients={rows(workspace.clients)} command={command}/>}
      {tab==='finance' && founder && <PlanSettings settings={rows(workspace.planSettings)} command={command}/>}
      {tab==='finance' && founder && <DiscountPolicies policies={rows(workspace.discountPolicies)} partners={rows(workspace.partners)} command={command}/>}
      {tab==='finance' && founder && <AdditionalClaims claims={rows(workspace.additionalClaims)} clients={rows(workspace.clients)} command={command}/>}
      {tab==='finance' && !founder && <PartnerCommercial allowances={rows(workspace.discountAllowances)} claims={rows(workspace.additionalClaims)} command={command}/>}
      {tab==='recruitment' && founder && <RecruitmentPanel workspace={workspace} command={command} invitation={invitation} clearInvitation={()=>setInvitation('')}/>}
      {tab==='recruitment' && founder && <ApplicantRetention applications={rows(workspace.applications)} command={command}/>}
      {tab==='capacity' && founder && <><Capacity data={rows(workspace.capacity)} founder/><section className="ex-panel"><h2>Assess remaining partner delivery allocation</h2><p>Review the <Link href="/operations/capacity">existing delivery forecast</Link> and account for current projects, retainers, founder availability and approved freelance support. This allocation is additional capacity available for partner opportunities, not total team hours.</p><Action action="capacity" title="Save assessed allocation" command={command}><Field name="period" title="Week starting (Monday)" type="date"/><Field name="hours" title="Available partner delivery hours" type="number"/><Field name="rationale" title="Assessment and existing commitments" area/><Check name="commitmentsReviewed" title="I reviewed existing projects, retainers and founder commitments"/></Action></section></>}
    </>}
    <footer className="ex-footer">SCALESMITHS INDEPENDENT PARTNER NETWORK<span>Commercial commitments remain subject to approval.</span></footer></main></div>
  </div>
}
function Metric({name,value,note}:{name:string;value:string;note:string}) {return <section className="ex-metric"><span>{name}</span><strong>{value}</strong><small>{note}</small></section>}
export function Empty({text}:{text:string}) {return <div className="ex-empty"><BriefcaseBusiness size={28}/><p>{text}</p></div>}
export function Field({name,title,type='text',required=true,area=false,value,placeholder}:{name:string;title:string;type?:string;required?:boolean;area?:boolean;value?:string;placeholder?:string}) {return <label className="ex-field">{title}{area?<textarea name={name} required={required} defaultValue={value} maxLength={30000} rows={3}/>:<input name={name} type={type} required={required} defaultValue={value} placeholder={placeholder} min={type==='number'?0:undefined} step={type==='number'?1:undefined} maxLength={2000}/>}</label>}
const BADGE_NAMES: Record<number,string> = {1:'First client',5:'Five clients',10:'Ten clients',25:'Twenty-five clients',50:'Fifty clients',100:'One hundred clients',250:'Two hundred and fifty clients',500:'Five hundred clients'}
