    <h3>Meeting requests</h3>{meetings.length?meetings.map(m=><details className="ex-resource" key={str(m.id)}><summary>{str(m.partner_name)} · {MEETING_LABELS[str(m.meeting_type)]||str(m.meeting_type)} <span className="ex-badge">{label(m.status)}</span></summary><p>{str(m.purpose)}</p><p>Preferred: {(Array.isArray(m.preferred_slots)?(m.preferred_slots as string[]):[]).join(' · ')} ({str(m.time_zone)}){m.business_name?` · ${str(m.business_name)}`:''}</p>{Boolean(m.context) && <p className="ex-prewrap">{str(m.context)}</p>}
      {!['declined','cancelled','completed'].includes(str(m.status)) && <Action action="decide_meeting" title="Record meeting decision" initial={{meetingId:m.id}} command={command}><Select name="decision" title="Decision" options={['review','request_information','propose_alternative','confirm','decline','cancel','complete']}/><Field name="start" title="Date and time (to propose or confirm)" type="datetime-local" required={false}/><Field name="note" title="Note to the partner" area required={false}/></Action>}
      <details><summary>Correct the submitted wording</summary><p>Closed requests are history. A correction is recorded with your reason and the before and after wording.</p><Action action="correct_meeting" title="Record correction" initial={{meetingId:m.id}} command={command}><Field name="purpose" title="Corrected purpose (leave blank to keep)" area required={false}/><Field name="context" title="Corrected supporting information (leave blank to keep)" area required={false}/><Field name="reason" title="Reason for the correction" area/></Action></details></details>):<Empty text="No meeting requests."/>}
    <h3>Toolkit fulfilment</h3>{partners.length?partners.map(p=><details className="ex-resource" key={str(p.id)}><summary>{str(p.name)}</summary>{rows(p.items).map(i=><div className="ex-list-row" key={str(i.key)}><span>{str(i.label)}{i.detail?` · ${str(i.detail)}`:''}</span><strong>{label(i.status)}</strong></div>)}
      <Action action="set_toolkit_item" title="Record fulfilment" initial={{partnerId:p.id}} command={command}><Select name="itemKey" title="Item" options={rows(p.items).map(i=>str(i.key))}/><Select name="status" title="Status" options={['not_requested','planned','awaiting_approval','in_preparation','available','completed','unavailable']}/><Field name="detail" title="Fulfilment evidence (required for available or completed)" area required={false}/></Action></details>):<Empty text="No activated partners."/>}</section>
}
function AchievementCentre({o}:{o:Row}) {
  if(!o.programme) return <Empty text="Achievements are not available yet."/>
  const next=(o.next||{}) as Row, programme=o.programme as Row, milestones=rows(o.milestones), count=Number(o.qualifiedClients||0)
  const nextM=next.next as Row|null
  return <section className="ex-panel"><p className="ex-overline">ACHIEVEMENT CENTRE</p><h2>{count} qualifying {count===1?'client':'clients'}</h2>
    <p>{nextM?`${count} of ${str(nextM.clients)} qualifying clients, next planned milestone: ${str(nextM.label)}.`:'You have reached every planned milestone.'}</p>
    <div role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(Number(next.fraction||0)*100)} aria-label="Progress to the next planned milestone" style={{height:10,borderRadius:6,background:'#2a2a2e',overflow:'hidden',margin:'12px 0'}}><div style={{width:`${Math.round(Number(next.fraction||0)*100)}%`,height:'100%',background:'linear-gradient(90deg,#a8884a,#ecd9a8)'}}/></div>
    <p>{Boolean(programme.planned)?'This is the planned schedule. It is not yet approved, and no reward is payable. Reaching a milestone does not by itself create any entitlement.':`Programme version ${str(programme.version)} is approved.${programme.financialRewardsEnabled?'':' Financial rewards are not enabled.'}`} Qualification is decided by a founder from verified client records. There are no targets, deadlines or penalties.</p>
    <div className="ex-metrics"><Metric name="Qualifying clients" value={str(count)} note="Counted from founder-reviewed client records"/><Metric name="Approved financial rewards" value={money(o.approvedBonusPence)} note="Only rewards a founder has approved under an approved programme"/><Metric name="Planned cumulative bonus at your count" value={money(o.plannedCumulativeBonusPence)} note="Illustration only, not an entitlement"/></div>
    <ol style={{display:'grid',gap:12,padding:0,listStyle:'none',marginTop:16}}>{milestones.map(m=>{const r=m.reward as Row|null;return <li key={str(m.clients)} className="ex-list-row" aria-label={`${BADGE_NAMES[Number(m.clients)]||str(m.clients)} milestone`}>
      <span><strong style={{display:'inline-block',minWidth:42,padding:'4px 10px',borderRadius:8,border:`1px solid ${m.reached?'#c8aa6e':'#555'}`,color:m.reached?'#ecd9a8':'#888',textAlign:'center'}}>{str(m.clients)}</strong> {str(m.label)}</span>
      <strong>{!m.reached?'Not yet reached':r?label(r.status):'Reached'}{m.reached&&r&&r.status==='conditional'?' · awaiting founder review':''}</strong></li>})}</ol>
    <p className="ex-badge">Badge names are working titles until approved by ScaleSmiths.</p></section>
}
function ReferralsPanel({o,command}:{o:Row;command:Command}) {
  const ref=(o.referral||{}) as Row, referred=rows(ref.referred)
  return <section className="ex-panel"><p className="ex-overline">REFERRALS</p><h2>Introduce another independent partner</h2>
    <p>Planned: a one-off £250 when a partner you refer is approved and acquires five qualifying clients. It is conditional, not yet payable, and each application is vetted exactly as normal. There is no downline, no recurring commission on anyone else&apos;s sales and no obligation to recruit.</p>
    {ref.code?<p>Your referral code: <code aria-label="Your referral code">{str(ref.code)}</code>. Give it to the applicant; a founder records the attribution before they are activated.</p>:<Action action="create_referral_code" title="Create my referral code" command={command}><p>One code per partner. It never changes.</p></Action>}
    <h3>Your referrals</h3>{referred.length?referred.map((r,i)=><div className="ex-list-row" key={i}><span>Referral {i+1} · {label(r.stage)} · {str(r.qualifiedClients)} of {str(r.threshold)} qualifying clients</span><strong>{r.rewardStatus?`Reward ${label(r.rewardStatus)}`:'No reward yet'}</strong></div>):<Empty text="No referral has been recorded."/>}
    <p>You see only a stage and a count. The referred partner&apos;s identity, customers and earnings stay private.</p></section>
