const CHECK_LABEL: Record<string,string> = {approved:'Approved',not_approved:'Not approved',unknown:'No country',clear:'Clear',cleared_by_founder:'Cleared by a founder',review_required:'Review required',restricted:'Restricted'}
function ResearchAdmin({r,sectors,exclusivities,command}:{r:Row;sectors:Row[];exclusivities:Row[];command:Command}) {
  const candidates=rows(r.candidates),events=rows(r.events),partners=rows(r.partners)
  const partnerSelect=(name:string)=><label className="ex-field">Partner<select name={name} required>{partners.map(p=><option key={str(p.id)} value={str(p.id)}>{str(p.display_name)} ({str(p.allocated)} held)</option>)}</select></label>
  const exLabel=(id:string)=>{const e=exclusivities.find(x=>str(x.id)===id);return e?`${str(e.client_name)} · ${str(e.sector)} · ${str(e.area)}`:id}
  return <section className="ex-panel"><p className="ex-overline">RESEARCHED PROSPECTS</p><h2>Research and allocation</h2>
    <p>A candidate is research from a public source. It is not a lead, and recording or allocating one never contacts the business. Allocation gives an active partner a prospect inside the normal workflow; the partner decides whether to approach it. Every gate is checked again at the moment of allocation.</p>
    <details open><summary>Record a researched business</summary><Action action="create_candidate" title="Create candidate" command={command}><div className="ex-form-grid"><Field name="businessName" title="Business name"/><Field name="website" title="Business website" placeholder="example.co.uk"/><Field name="industry" title="Industry (as described publicly)" required={false}/>
      <label className="ex-field">Canonical sector<select name="sectorId"><option value="">Unclassified (review required if an exclusivity could apply)</option>{sectors.map(x=><option key={str(x.id)} value={str(x.id)}>{str(x.label)}</option>)}</select></label>
      <Field name="country" title="Country, two-letter code such as GB"/><Field name="region" title="Region" required={false}/><Field name="area" title="Area or town" required={false}/><Field name="publicSource" title="Public source (page or directory where it was found)"/><Field name="researchedOn" title="Research date" type="date"/>
      <Field name="partnerNotes" title="Research notes the allocated partner may see" area required={false}/><Field name="internalNotes" title="Internal notes (founders only)" area required={false}/></div></Action></details>
    <details><summary>Suppress a business domain</summary><p>A suppressed domain can never be registered or allocated.</p><Action action="suppress" title="Record suppression" command={command}><Field name="domain" title="Business website or domain"/><Field name="reason" title="Reason" area/></Action></details>
    <h3>Candidates</h3>{candidates.length?candidates.map(c=>{const checks=(c.checks||null) as Row|null;const history=events.filter(e=>str(e.candidate_id)===str(c.id));const status=str(c.status)
      return <details className="ex-resource" key={str(c.id)}><summary>{str(c.business_name)} · {str(c.country)} <span className="ex-badge">{label(status)}</span>{Boolean(c.partner_name) && <span className="ex-badge">{str(c.partner_name)}</span>}</summary>
      <dl><div><dt>Website</dt><dd>{str(c.website_url)}</dd></div><div><dt>Public source</dt><dd>{str(c.public_source)}</dd></div><div><dt>Researched</dt><dd>{str(c.researched_on).slice(0,10)}</dd></div><div><dt>Sector</dt><dd>{str(c.sector_label||c.industry)||'Unclassified'}</dd></div>{Boolean(c.internal_notes) && <div><dt>Internal notes</dt><dd className="ex-prewrap">{str(c.internal_notes)}</dd></div>}</dl>
      {checks && <div className="ex-checks"><p><strong>Checks (live)</strong></p><ul>
        <li>Existing client: {checks.existingClient?'MATCH':'none'}</li><li>Existing prospect or registration: {checks.existingProspect?'MATCH':'none'}</li><li>Suppression: {checks.suppressed?'SUPPRESSED':'none'}</li><li>Market: {CHECK_LABEL[str(checks.market)]}</li><li>Exclusivity: {CHECK_LABEL[str(checks.exclusivity)]}</li><li>Marketing screening: {label(checks.screening)}</li></ul>
        {rows(checks.blockers).length>0 || (Array.isArray(checks.blockers)&&checks.blockers.length>0) ? <p>Blocked: {(checks.blockers as string[]).join(' ')}</p> : <p>No blockers at this moment.</p>}</div>}
      {['draft','eligible'].includes(status) && <><Action action="record_screening" title="Record marketing screening" initial={{candidateId:c.id}} command={command}><Select name="outcome" title="Outcome" options={['evidenced','failed']}/><Field name="evidence" title="Screening evidence (required; never assumed)" area/></Action>
        {checks && ['review_required'].includes(str(checks.exclusivity)) && <Action action="clear_candidate_exclusivity" title="Clear an exclusivity review" initial={{candidateId:c.id}} command={command}><label className="ex-field">Exclusivity under review<select name="exclusivityId">{(checks.unresolvedExclusivityIds as string[]).map(id=><option key={id} value={id}>{exLabel(id)}</option>)}</select></label><Field name="reference" title="Decision evidence and reference"/></Action>}</>}
      {status==='draft' && <Action action="mark_candidate_eligible" title="Mark eligible (re-runs every check)" initial={{candidateId:c.id}} command={command}/>}
      {status==='eligible' && <Action action="allocate_candidate" title="Allocate to a partner" initial={{candidateId:c.id}} command={command}>{partnerSelect('partnerId')}</Action>}
      {status==='allocated' && <><Action action="reassign_candidate" title="Reassign to another partner" initial={{candidateId:c.id}} command={command}>{partnerSelect('partnerId')}<Field name="note" title="Reason for reassignment"/></Action><Action action="release_candidate" title="Release from the partner" initial={{candidateId:c.id}} command={command}><Field name="note" title="Reason for release"/></Action></>}
      {status==='excluded' && <Action action="release_candidate_domain" title="Release the held domain" initial={{candidateId:c.id}} command={command}><p>If this candidate was ever allocated, its withdrawn prospect still holds the domain and blocks a corrected re-entry. Releasing it is audited and permanent; the prospect, the partner history and every suppression and existing-client check stay in force.</p><Field name="reason" title="Reason for releasing the domain"/></Action>}
      {['draft','eligible'].includes(status) && <Action action="exclude_candidate" title="Exclude this candidate" initial={{candidateId:c.id}} command={command}><Field name="reason" title="Reason for exclusion"/></Action>}
      <h4>History</h4>{history.length?<ol className="ex-history">{history.map((e,i)=><li key={i}>{new Date(str(e.created_at)).toLocaleString('en-GB')} · {label(e.event)} · {str(e.actor_name)}{e.partner_name?` → ${str(e.partner_name)}`:''}{e.from_partner_name?` (from ${str(e.from_partner_name)})`:''}{e.note?` · ${str(e.note)}`:''}</li>)}</ol>:<p>No history.</p>}</details>}):<Empty text="No researched candidates yet."/>}</section>
}

