      {status==='approved' && <><h4>Approved benefits and fulfilment</h4>{bs.length?<ul>{bs.map(b=><li key={str(b.id)}>{str(b.benefit)} · <strong>{b.outcome?`${label(b.outcome)}: ${str(b.fulfilment_note)}`:'Approved'}</strong>{!b.outcome && <Action action="record_benefit_fulfilment" title="Record outcome" initial={{benefitId:b.id}} command={command}><Select name="outcome" title="Outcome" options={['fulfilled','withdrawn']}/><Field name="note" title="Fulfilment note"/></Action>}</li>)}</ul>:<p>No benefits approved.</p>}
