export async function activatePartnerInvitation(tokenInput: unknown, passwordInput: unknown, acceptanceInput?: unknown): Promise<void> {
  requirePartnerActivationEnabled()
  const credential = validateActivationCredential(tokenInput, passwordInput)
  // Hash before locking to bound lock duration. Rate limiting precedes this service.
  const passwordHash = await bcrypt.hash(credential.password, 12)
  const activated = await db.transaction(async (tx) => {
    const result = await tx.execute(sql`select p.id, p.user_id, p.application_id, p.operating_country from expansion_partners p join admin_users u on u.id = p.user_id join partner_applications a on a.id = p.application_id where p.invitation_hash = ${invitation
    const invitation = result.rows[0] as { id: string; user_id: string; application_id: number; operating_country: string } | undefined
    if (!invitation) throw new AdminIdentityError("Invitation is invalid or unavailable.", 400, "invitation_invalid")
    // Re-checked at the moment of activation: a market suspended after the invitation was issued stops the activation, and nothing is consumed.
    await assertOperatingMarketApproved(tx, invitation.operating_country, "operating_market_not_approved", "Activation is not available for this market yet. Contact ScaleSmiths.")
    // The partner accepts the exact issued version while still inactive; the database refuses activation without it.
    const { acceptanceId, agreement } = await acceptOnActivation(tx, invitation.id, invitation.user_id, acceptanceInput)
    const now = new Date()
    await tx.update(adminUsers).set({ passwordHash, active: true, passwordChangedAt: now, sessionVersion: sql`${adminUsers.sessionVersion} + 1`, updatedAt: now }).where(eq(adminUsers.id, invitation.user_id))
    await tx.execute(sql`update expansion_partners set invitation_hash = null, invitation_expires_at = null, activated_at = ${now} where id = ${invitation.id}`)
    await tx.execute(sql`update partner_applications set status = 'activated' where id = ${invitation.application_id}`)
    await tx.insert(adminSecurityAudit).values({ actorUserId: invitation.user_id, targetUserId: invitation.user_id, action: "partner_activated", success: true, metadataJson: { partnerId: invitation.id, applicationId: invitation.application_id, acceptanceId, ag
    const [identity] = await tx.select({ email: adminUsers.email, name: adminUsers.displayName }).from(adminUsers).where(eq(adminUsers.id, invitation.user_id)).limit(1)
    return { partnerId: invitation.id, applicationId: invitation.application_id, email: identity.email, name: identity.name }
  })
  // Welcome email after the activation has committed; its outcome never affects the activation.
  try {
    await db.transaction((tx) => notifyPartner(tx, { to: activated.email, partnerId: activated.partnerId, applicationId: activated.applicationId, idempotencyKey: `activated-${activated.partnerId}`,
      email: { kind: "activated", name: activated.name, signInUrl: `${partnerPortalOrigin()}/login` } }))
  } catch { /* recorded as a warning by the notifier; activation already succeeded */ }
}
import { NextResponse } from "next/server"
import { AdminIdentityError } from "@/lib/admin-users"
import { checkLoginRateLimit, getAuthRequestIp, loginRateLimitKeys } from "@/lib/login-limiter"
import { activatePartnerInvitation, previewInvitationAgreement, requirePartnerActivationEnabled } from "@/lib/server/partner-invitations"

export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  const headers = { "Cache-Control": "private, no-store", "Referrer-Policy": "no-referrer" }
  try {
    const origin = request.headers.get("origin")
    const expectedOrigin = process.env.AUTH_URL ? new URL(process.env.AUTH_URL).origin : new URL(request.url).origin
    if (origin !== expectedOrigin) return NextResponse.json({ error: "Invalid request origin." }, { status: 403, headers })
    requirePartnerActivationEnabled()
    if (!await checkLoginRateLimit(loginRateLimitKeys("partner-activation", getAuthRequestIp(request), ""))) return NextResponse.json({ error: "Too many attempts. Try again later." }, { status: 429, headers })
    if (!request.headers.get("content-type")?.startsWith("application/json")) return NextResponse.json({ error: "JSON is required." }, { status: 415, headers })
    const reader = request.body?.getReader()
    if (!reader) throw new AdminIdentityError("Invalid request.")
    let body = ""
    let size = 0
    const decoder = new TextDecoder()
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      size += value.byteLength
      if (size > 8192) { await reader.cancel(); return NextResponse.json({ error: "Request is too large." }, { status: 413, headers }) }
      body += decoder.decode(value, { stream: true })
    }
    body += decoder.decode()
    let payload: Record<string, unknown>
    try { payload = JSON.parse(body) } catch { throw new AdminIdentityError("Invalid request.") }
    if (!payload || typeof payload !== "object" || Array.isArray(payload)) throw new AdminIdentityError("Invalid request.")
    // Step one shows the issued agreement in full; step two activates only with an explicit acceptance of that exact text.
    if (payload.action === "preview") return NextResponse.json({ agreement: await previewInvitationAgreement(payload.token) }, { headers })
    await activatePartnerInvitation(payload.token, payload.password, payload.acceptance)
    return NextResponse.json({ ok: true }, { headers })
  } catch (error) {
    return NextResponse.json({ error: error instanceof AdminIdentityError ? error.safeMessage : "Activation is unavailable. Try again later." }, { status: error instanceof AdminIdentityError ? error.status : 503, headers })
  }
}
