${body}${button}
${footnote ? `<p style="margin:0;color:#8f96a2;font-size:12px;line-height:1.6;">${footnote}</p>` : ""}
</td></tr>
<tr><td style="padding:16px 28px;border-top:1px solid #2a2b30;font-family:Arial,Helvetica,sans-serif;color:#7f8692;font-size:11px;line-height:1.6;">ScaleSmiths Ltd, United Kingdom. You are receiving this because you appl
</table></td></tr></table></body></html>`
}
