// B2.10 PostgreSQL 14 rehearsal assertions (CI's checks plus 0105/0106 coverage). Prints verdicts only, never credentials.
import { createRequire } from "node:module"
const pg = createRequire("D:/tmp/ss-b210/admin/package.json")("pg")
const c = new pg.Client({ connectionString: process.env.ADMIN_DATABASE_URL }); await c.connect()
const w = new pg.Client({ connectionString: process.env.WEB_DATABASE_URL }); await w.connect()
try {
  const v = (await c.query("show server_version")).rows[0].server_version
  if (!v.startsWith("14.")) throw Error("Expected PostgreSQL 14, got " + v)
  const ctl = await c.query("select suspended from ascend_automation_controls where scope='global'")
  if (ctl.rowCount !== 1 || ctl.rows[0].suspended !== true) throw Error("ASCEND global stop must default on")
  const d = await c.query("select count(*)::int total, count(*) filter (where enabled)::int enabled from ascend_automation_definitions")
  if (d.rows[0].total !== 5 || d.rows[0].enabled !== 0) throw Error("ASCEND definitions must default disabled")
  for (const t of ["expansion_onboarding_progress", "partner_password_resets", "partner_application_withdrawals"]) {
    const ad = await c.query("select has_table_privilege(current_user,$1,'SELECT') s, has_table_privilege(current_user,$1,'INSERT') i", ["public." + t])
    if (!ad.rows[0].s || !ad.rows[0].i) throw Error("admin role lacks grants on " + t)
    const wb = await w.query("select has_table_privilege(current_user,$1,'SELECT') s", ["public." + t])
    if (wb.rows[0].s) throw Error("public web role must not read " + t)
  }
  const ex = await w.query("select has_table_privilege(current_user,'public.ascend_executions','SELECT') r")
  if (ex.rows[0].r) throw Error("public web role must not read ASCEND executions")
  const k = (await c.query("select pg_get_constraintdef(oid) d from pg_constraint where conname='partner_notifications_kind_check'")).rows[0].d
  for (const kind of ["application_received", "information_requested", "application_declined", "invitation", "activated", "agreement_reissued", "password_reset", "withdrawal_confirmation"]) if (!k.includes(kind)) throw Error("notification kind missing: " + kind)
  const n = (await c.query("select count(*)::int n from drizzle.__drizzle_migrations")).rows[0]?.n
  console.log(`PostgreSQL ${v}: every migration applied incl. 0105 and 0106 (${n ?? "?"} admin journal rows); ASCEND disabled by default; new tables least-privilege; notification kinds a strict superset: passed`)
} finally { await w.end(); await c.end() }

