      expect((await anon.request.post(`${origin()}${path}`, { headers: { origin: origin() }, data: { action: 'nonsense' } })).status()).toBe(400)
    }
    await anon.close()
  })

  await fa.context.close(); await fb.context.close(); await p1.context.close()
  expect(consoleErrors).toEqual([])
